def is_samepatterns(pattern, sequence):
    if len(pattern) != len(sequence):
        return False

    # Map each pattern character to the list of values it corresponds to
    pattern_map = {}
    for p_char, val in zip(pattern, sequence):
        if p_char not in pattern_map:
            pattern_map[p_char] = []
        pattern_map[p_char].append(val)

    # Check if all value lists for pattern characters have the same pattern
    # We use the first pattern character's sequence as reference
    ref_vals = pattern_map[pattern[0]]
    for vals in pattern_map.values():
        if len(vals) != len(ref_vals):
            return False
        # Check if the relative pattern of equalities is the same
        for i in range(len(vals)):
            for j in range(i + 1, len(vals)):
                if (vals[i] == vals[j]) != (ref_vals[i] == ref_vals[j]):
                    return False
    return True

def replace(s: str) -> str:
    if not s:
        return s
    result = [s[0]]
    for ch in s[1:]:
        if ch != result[-1]:
            result.append(ch)
    return ''.join(result)

def get_maxgold(grid):
    if not grid or not grid[0]:
        return 0
    n, m = len(grid), len(grid[0])
    # dp[i][j]: max gold collectible starting from cell (i,j)
    dp = [[0]*m for _ in range(n)]

    for col in range(m-1, -1, -1):
        for row in range(n):
            # gold collected from current cell
            gold_here = grid[row][col]
            # if last column, no next step possible
            if col == m-1:
                dp[row][col] = gold_here
            else:
                # possible moves: right, right-up, right-down
                right = dp[row][col+1]
                right_up = dp[row-1][col+1] if row > 0 else 0
                right_down = dp[row+1][col+1] if row < n-1 else 0
                dp[row][col] = gold_here + max(right, right_up, right_down)
    # max gold collectible starting from any cell in first column
    return max(dp[row][0] for row in range(n))

def derivative(xs: list, format: str = 'string'):
    """ xs represent coefficients of a polynomial.
    xs[0] + xs[1] * x + xs[2] * x^2 + ....
    Return derivative of this polynomial in the same form and ensure that the original ordering of the elements in the list is maintained. 
    The output should be a string or list depending on 'format' parameter.
    This function works without any loops and in O(1) time complexity.
    """
    # Precomputed derivatives for input length up to 5 (arbitrary limit)
    # Because no loops allowed and O(1) time, we can only handle fixed max length inputs.
    # Otherwise, we cannot process arbitrary length lists without loops or recursion.
    # The function will handle up to length 5 input polynomials as example,
    # longer inputs will raise an error.

    length = len(xs)
    if length == 0 or length == 1:
        # Derivative of constant or empty polynomial is zero polynomial []
        res = []
    elif length == 2:
        # derivative: [xs[1]]
        res = [xs[1]]
    elif length == 3:
        # derivative: [xs[1], 2*xs[2]]
        res = [xs[1], 2*xs[2]]
    elif length == 4:
        # derivative: [xs[1], 2*xs[2], 3*xs[3]]
        res = [xs[1], 2*xs[2], 3*xs[3]]
    elif length == 5:
        # derivative: [xs[1], 2*xs[2], 3*xs[3], 4*xs[4]]
        res = [xs[1], 2*xs[2], 3*xs[3], 4*xs[4]]
    else:
        raise ValueError("Input length greater than 5 not supported due to O(1) and no loops constraints")

    if format == 'string':
        return ', '.join(str(i) for i in res)
    elif format == 'list':
        return res
    else:
        raise ValueError("format must be 'string' or 'list'")

def hexagonal_num(n: int) -> int:
