        raise ValueError("Input must be a positive integer.")
    return n * (2 * n - 1)

def f(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer.")

    def factorial(x):
        result = 1
        for num in range(1, x + 1):
            result *= num
        return result

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(i * (i + 1) // 2)
    return result

def count_pairs(a, k):
    count = 0
    n = len(a)
    for i in range(n):
        for j in range(i, n):
            if abs(a[i] - a[j]) == k:
