def re_arrange_tuples(lst, order):
    # Map first elements to their tuples
    first_to_tuple = {t[0]: t for t in lst}
    used = set()
    result = []
    for key in order:
        tup = first_to_tuple.get(key)
        if tup is not None and tup not in used:
            result.append(tup)
            used.add(tup)
    return result
